const parsed = await browserjs(tabId, async () => {
  const resp = window.ytInitialPlayerResponse;
  const captionTracks = resp?.captions?.playerCaptionsTracklistRenderer?.captionTracks;
  const track = captionTracks.find(t => t.vssId === ".en-US") || captionTracks[0];
  const res = await fetch(track.baseUrl);
  const xml = await res.text();
  const parser = new DOMParser();
  const doc = parser.parseFromString(xml, "text/xml");
  const textNodes = Array.from(doc.querySelectorAll("text"));
  return textNodes.map(n => ({
