  const resp = window.ytInitialPlayerResponse;
  const captionTracks = resp?.captions?.playerCaptionsTracklistRenderer?.captionTracks;
  const track = captionTracks.find(t => t.vssId === ".en-US") || captionTracks[0];
  const res = await fetch(track.baseUrl);
  const xml = await res.text();
  const parser = new DOMParser();
  const doc = parser.parseFromString(xml, "text/xml");
  const textNodes = Array.from(doc.querySelectorAll("text"));
  return textNodes.map(n => ({
    start: parseFloat(n.getAttribute("start")),
    dur: parseFloat(n.getAttribute("dur")),
    text: n.textContent
  }));
});

// Search for dataset keywords
const keywords = ["dataset", "data", "imagenet", "pascal", "voc", "cifar", "mnist", "caltech", "coco"];
const matches = parsed.filter(item => {
  const lower = item.text.toLowerCase();
  return keywords.some(k => lower.includes(k));
});

console.log(`Found ${matches.length} matching lines. First 20:`);
console.log(JSON.stringify(matches.slice(0, 30), null, 2));
"}

