const sampledCaptions = await browserjs(tabId, async () => {
  const p = document.getElementById('movie_player');
  const results = [];
  // Sample from 15:00 (900s) to 45:00 (2700s) in 40-second increments
  for (let t = 900; t <= 2700; t += 40) {
    p.seekTo(t, true);
    await new Promise(r => setTimeout(r, 350));
    const caption = Array.from(document.querySelectorAll('.ytp-caption-segment')).map(s => s.textContent).join(' ');
    results.push({
      seconds: t,
      timestamp: `${Math.floor(t / 60)}:${(t % 60).toString().padStart(2, '0')}`,
      caption
    });
  }
  return results;
});

// Let's filter or inspect what was found
const hits = sampledCaptions.filter(c => {
  const l = c.caption.toLowerCase();
  return l.includes('data') || l.includes('image') || l.includes('pascal') || l.includes('voc') || 
         l.includes('cifar') || l.includes('mnist') || l.includes('caltech') || l.includes('net') ||
         l.includes('challenge') || l.includes('benchmark') || l.includes('object');
});

console.log(`Sampled ${sampledCaptions.length} points. Matches: ${hits.length}`);
