// Deduplicate consecutive identical captions
function dedup(arr) {
  const out = [];
  for (const item of arr) {
    if (out.length === 0 || out[out.length - 1].caption !== item.caption) {
      if (item.caption) out.push(item);
    }
  }
  return out;
}

