    await new Promise(r => setTimeout(r, 200));
    const caption = Array.from(document.querySelectorAll('.ytp-caption-segment')).map(s => s.textContent).join(' ');
    const m = Math.floor(t / 60);
    const s = (t % 60).toString().padStart(2, '0');
    res.push({ timestamp: `${m}:${s}`, t, caption });
  }
  return res;
});

// Deduplicate consecutive identical captions
function dedup(arr) {
  const out = [];
  for (const item of arr) {
    if (out.length === 0 || out[out.length - 1].caption !== item.caption) {
      if (item.caption) out.push(item);
    }
  }
  return out;
}

console.log("=== Window 1 (24:00 - 26:30) ===");
console.log(JSON.stringify(dedup(p1), null, 2));

console.log("=== Window 2 (30:30 - 31:30) ===");
console.log(JSON.stringify(dedup(p2), null, 2));

console.log("=== Window 3 (32:00 - 33:30) ===");
console.log(JSON.stringify(dedup(p3), null, 2));
"}

